		new BreakpointTimeOverviewEventListener();
	private Map<CellType, Color> colorMap = new();
	private Map<Integer, Long> indexToSnap = new();
	private Map<Long, Color> snapToColor = new();
	private Map<Long, string> snapToTooltip = new();
	private Map<Long, ULongSpan> snapToRange = new();
	Trace currentTrace;
	TimeOverviewColorComponent overviewComponent;
